            aWandererF = aWandererF ^ ((RotL64(aIngress, 21U) + RotL64(aOrbiterF, 11U)) + aOrbiterH);
            aWandererH = aWandererH + (((RotL64(aScatter, 43U) + aOrbiterC) + RotL64(aOrbiterD, 47U)) + RotL64(aCarry, 57U));
