            aOrbiterA = (((aWandererF + RotL64(aCross, 43U)) + RotL64(aCarry, 13U)) + 0x8D9BF14732975B55ULL) + aNonceWordM;
            aOrbiterH = ((aWandererJ + RotL64(aScatter, 51U)) + RotL64(aCarry, 47U)) + 0x6F1772AC441E82D8ULL;
