            aOrbiterC = ((aWandererE + RotL64(aIngress, 29U)) + 0xE339A648CE5CCC6DULL) + aNonceWordE;
            aOrbiterD = ((((aWandererG + RotL64(aPrevious, 11U)) + RotL64(aCarry, 35U)) + 0x473DB74E9AE399A6ULL) + aPhaseAOrbiterAssignSaltC[(((31U - aIndex) + 3U)) & S_SALT1]) + aNonceWordP;
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0xB8FDBBBC375CF2F5ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0x9E2064DF39158EDDULL) ^ aNonceWordO;
            aOrbiterA = RotL64((aOrbiterA * 0xF41D1AA8BF84FAC9ULL), 53U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x388E7D72D1F3404DULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterH) ^ 0x6D34BC433678AC79ULL) ^ aPhaseAOrbiterUpdateSaltC[((aIndex + 20U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x63DFB44152D8A769ULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x84FD37A7101E1B50ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0x02CC5144D12D7B6DULL) ^ aPhaseAOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x4D4C1D17EEE2BBBFULL), 19U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x7BED84541277F5B0ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterA) ^ 0xF4920F4221B96B18ULL) ^ aNonceWordF;
            aOrbiterH = RotL64((aOrbiterH * 0x3E098F9AA708D891ULL), 41U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterG) + 0xB8233E6AC51A3934ULL) + aNonceWordB;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0xDF990F285E7D4E9CULL;
            aOrbiterF = RotL64((aOrbiterF * 0x62D451FAC481864BULL), 35U);
            //
            aOrbiterC = (((aOrbiterC + aOrbiterH) + 0xBA834657463A8699ULL) + aPhaseAOrbiterUpdateSaltB[((aIndex + 10U)) & S_SALT1]) + aNonceWordK;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x0310DF6386429789ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xEFE442DF4D55D8D9ULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x1D38A14B625252D5ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterF) ^ 0xD6949E86150B87D5ULL) ^ aPhaseAOrbiterUpdateSaltD[((aIndex + 19U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xE144CDCBD7A81BA5ULL), 11U);
