            //
            aWandererG = aWandererG ^ (((RotL64(aCross, 41U) + aOrbiterG) + RotL64(aOrbiterK, 57U)) + aNonceWordN);
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 3U) + aOrbiterA) + RotL64(aOrbiterF, 5U)) + RotL64(aCarry, 51U));
            aWandererI = aWandererI ^ (((RotL64(aIngress, 35U) + aOrbiterF) + RotL64(aOrbiterD, 11U)) + aPhaseAWandererUpdateSaltB[((aIndex + 14U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aScatter, 57U) + RotL64(aOrbiterK, 43U)) + aOrbiterC) + RotL64(aCarry, 19U));
            aWandererE = aWandererE ^ ((((RotL64(aCross, 10U) + aOrbiterA) + RotL64(aOrbiterH, 18U)) + aNonceWordI) + aPhaseAWandererUpdateSaltD[(((31U - aIndex) + 23U)) & S_SALT1]);
