            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x2A1A9960F36E19EEULL;
            aOrbiterK = RotL64((aOrbiterK * 0x7214FD659FCF1ECBULL), 51U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterI) + 0xA3501D5980A6C977ULL) + aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 16U)) & S_SALT1];
