            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x8F347919B3EC6534ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterF) ^ 0xDA1FAE02824867ACULL) ^ aPhaseBOrbiterUpdateSaltA[((aIndex + 11U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x6D891E0C5484682BULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x713F2BA3FAC24EDDULL;
