            //
            aOrbiterD = ((aWandererK + RotL64(aCross, 47U)) + RotL64(aCarry, 35U)) + 0xF4573A670B953341ULL;
            aOrbiterF = (aWandererA + RotL64(aScatter, 41U)) + 0x82535AEE79C80C3CULL;
            aOrbiterB = ((aWandererI + RotL64(aIngress, 21U)) + RotL64(aCarry, 51U)) + 0x27240B427646D975ULL;
            aOrbiterA = ((aWandererD + RotL64(aPrevious, 29U)) + 0xE551C4CB946B85E1ULL) + aPhaseAOrbiterAssignSaltF[((aIndex + 11U)) & S_SALT1];
            aOrbiterH = ((aWandererG + RotL64(aCross, 11U)) + 0x2C939B335F99B80EULL) + aPhaseAOrbiterAssignSaltB[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterG = (aWandererF + RotL64(aIngress, 53U)) + 0x8B7325052423EEB6ULL;
            aOrbiterI = ((aWandererH + RotL64(aScatter, 60U)) + RotL64(aCarry, 3U)) + 0x36E5EF65F9F187AEULL;
            //
            aOrbiterD = ((aOrbiterD + aOrbiterF) + 0xE8B7CAA649AFDDE0ULL) + aPhaseAOrbiterUpdateSaltC[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x67B4892352920C6CULL;
