            aOrbiterA = RotL64((aOrbiterA * 0xA76E1490771C4ABDULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x77AA40B32D5F095FULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x16A35E62D232680FULL;
