            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xB5390ED10EDB0BC7ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterF) ^ 0x68A8FB11B487DD89ULL) ^ aPhaseAOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
