            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x5F8F2EE6E86F9874ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x5766416864405866ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x25A3B3B5A43C324BULL), 51U);
            //
            aIngress = RotL64(aOrbiterG, 35U) ^ aOrbiterA;
