            aWandererG = aWandererG ^ (((RotL64(aIngress, 37U) + RotL64(aOrbiterG, 35U)) + aOrbiterA) + aPhaseAWandererUpdateSaltB[(((31U - aIndex) + 13U)) & S_SALT1]);
