            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x7086889D7640EF06ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0x734965B0D1898571ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xC1D3A22DAD1FD0D7ULL), 5U);
